import React, { useState } from 'react';
import { 
  Bell,
  Search,
  Menu,
  Plus,
  Filter,
  MoreHorizontal,
  Calendar,
  CheckCircle,
  Clock,
  AlertCircle,
  Edit3,
  Trash2,
  Eye,
  FolderKanban
} from 'lucide-react';
import Sidebar from './Sidebar';
import { useAuth } from '../context/AuthContext';

const Projects = () => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');

  const projects = [
    { 
      id: 1,
      name: 'E-Commerce Platform', 
      client: 'TechStore Inc.', 
      status: 'In Progress', 
      progress: 75, 
      deadline: 'Dec 15, 2024',
      budget: '$12,000',
      tasks: 24,
      completedTasks: 18
    },
    { 
      id: 2,
      name: 'Portfolio Website', 
      client: 'Design Studio', 
      status: 'Completed', 
      progress: 100, 
      deadline: 'Dec 10, 2024',
      budget: '$5,500',
      tasks: 12,
      completedTasks: 12
    },
    { 
      id: 3,
      name: 'Mobile App UI', 
      client: 'StartUp Hub', 
      status: 'In Review', 
      progress: 90, 
      deadline: 'Dec 20, 2024',
      budget: '$8,000',
      tasks: 20,
      completedTasks: 18
    },
    { 
      id: 4,
      name: 'Admin Dashboard', 
      client: 'Enterprise Co.', 
      status: 'In Progress', 
      progress: 60, 
      deadline: 'Dec 25, 2024',
      budget: '$15,000',
      tasks: 35,
      completedTasks: 21
    },
    { 
      id: 5,
      name: 'Landing Page', 
      client: 'Marketing Pro', 
      status: 'Pending', 
      progress: 10, 
      deadline: 'Jan 5, 2025',
      budget: '$3,000',
      tasks: 8,
      completedTasks: 1
    },
    { 
      id: 6,
      name: 'CRM System', 
      client: 'SalesForce Ltd.', 
      status: 'In Progress', 
      progress: 45, 
      deadline: 'Jan 15, 2025',
      budget: '$25,000',
      tasks: 50,
      completedTasks: 22
    }
  ];

  const filteredProjects = projects.filter(project => {
    const matchesSearch = project.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         project.client.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'all' || project.status === statusFilter;
    return matchesSearch && matchesStatus;
  });


  const getStatusColor = (status) => {
    switch(status) {
      case 'Completed': return 'bg-green-500/10 text-green-400 border-green-500/20';
      case 'In Progress': return 'bg-blue-500/10 text-blue-400 border-blue-500/20';
      case 'In Review': return 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20';
      case 'Pending': return 'bg-gray-500/10 text-gray-400 border-gray-500/20';
      default: return 'bg-gray-500/10 text-gray-400';
    }
  };

  const getStatusIcon = (status) => {
    switch(status) {
      case 'Completed': return CheckCircle;
      case 'In Progress': return Clock;
      case 'In Review': return AlertCircle;
      case 'Pending': return Clock;
      default: return Clock;
    }
  };

  return (
    <div className="min-h-screen bg-[#0a1628] flex">
      <Sidebar sidebarOpen={sidebarOpen} setSidebarOpen={setSidebarOpen} />

      {/* Main Content */}
      <main className="flex-1 min-w-0">
        {/* Header */}
        <header className="sticky top-0 z-20 bg-[#0a1628]/80 backdrop-blur-md border-b border-white/5 px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <button
                onClick={() => setSidebarOpen(true)}
                className="lg:hidden p-2 rounded-lg text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
              >
                <Menu className="w-6 h-6" />
              </button>
              <h2 className="text-xl font-semibold text-white">Projects</h2>
            </div>

            <div className="flex items-center gap-4">
              {/* Notifications */}
              <button className="relative p-2 rounded-xl bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 transition-colors">
                <Bell className="w-5 h-5" />
                <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full"></span>
              </button>

              {/* User */}
              <div className="w-10 h-10 rounded-full bg-blue-600 flex items-center justify-center">
                <span className="text-sm font-semibold text-white">RA</span>
              </div>
            </div>
          </div>
        </header>

        {/* Projects Content */}
        <div className="p-6">
          {/* Stats Bar */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
            {[
              { label: 'Total Projects', value: projects.length, color: 'blue' },
              { label: 'In Progress', value: projects.filter(p => p.status === 'In Progress').length, color: 'yellow' },
              { label: 'Completed', value: projects.filter(p => p.status === 'Completed').length, color: 'green' },
              { label: 'Pending', value: projects.filter(p => p.status === 'Pending').length, color: 'gray' }
            ].map((stat, index) => (
              <div key={index} className="bg-[#0f172a] rounded-xl p-4 border border-white/5">
                <p className="text-gray-400 text-sm mb-1">{stat.label}</p>
                <p className={`text-2xl font-bold ${
                  stat.color === 'blue' ? 'text-blue-400' :
                  stat.color === 'yellow' ? 'text-yellow-400' :
                  stat.color === 'green' ? 'text-green-400' :
                  'text-gray-400'
                }`}>{stat.value}</p>
              </div>
            ))}
          </div>

          {/* Actions Bar */}
          <div className="flex flex-col sm:flex-row gap-4 mb-6">
            {/* Search */}
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
              <input
                type="text"
                placeholder="Search projects..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-3 rounded-xl bg-[#0f172a] border border-white/10 text-white text-sm placeholder-gray-500 focus:outline-none focus:border-blue-500"
              />
            </div>

            {/* Filter */}
            <div className="flex gap-2">
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="px-4 py-3 rounded-xl bg-[#0f172a] border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
              >
                <option value="all">All Status</option>
                <option value="In Progress">In Progress</option>
                <option value="Completed">Completed</option>
                <option value="In Review">In Review</option>
                <option value="Pending">Pending</option>
              </select>

              <button className="flex items-center gap-2 px-4 py-3 bg-blue-600 text-white rounded-xl hover:bg-blue-500 transition-colors">
                <Plus className="w-4 h-4" />
                <span className="hidden sm:inline">New Project</span>
              </button>
            </div>
          </div>

          {/* Projects Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {filteredProjects.map((project) => {
              const StatusIcon = getStatusIcon(project.status);
              return (
                <div 
                  key={project.id}
                  className="bg-[#0f172a] rounded-2xl border border-white/5 overflow-hidden hover:border-blue-500/20 transition-all group"
                >
                  {/* Card Header */}
                  <div className="p-6 border-b border-white/5">
                    <div className="flex items-start justify-between mb-4">
                      <span className={`px-3 py-1 rounded-full text-xs font-medium border flex items-center gap-1.5 ${getStatusColor(project.status)}`}>
                        <StatusIcon className="w-3 h-3" />
                        {project.status}
                      </span>
                      <button className="p-1 rounded-lg text-gray-400 hover:text-white hover:bg-white/10 transition-colors">
                        <MoreHorizontal className="w-4 h-4" />
                      </button>
                    </div>
                    <h3 className="text-lg font-semibold text-white mb-1">{project.name}</h3>
                    <p className="text-sm text-gray-400">{project.client}</p>
                  </div>

                  {/* Card Body */}
                  <div className="p-6 space-y-4">
                    {/* Progress */}
                    <div>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-sm text-gray-400">Progress</span>
                        <span className="text-sm font-medium text-white">{project.progress}%</span>
                      </div>
                      <div className="h-2 bg-white/10 rounded-full overflow-hidden">
                        <div 
                          className={`h-full rounded-full transition-all ${
                            project.progress === 100 ? 'bg-green-500' : 'bg-blue-500'
                          }`}
                          style={{ width: `${project.progress}%` }}
                        ></div>
                      </div>
                    </div>

                    {/* Stats */}
                    <div className="grid grid-cols-2 gap-4 pt-4 border-t border-white/5">
                      <div className="flex items-center gap-2">
                        <Calendar className="w-4 h-4 text-gray-500" />
                        <span className="text-sm text-gray-400">{project.deadline}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-medium text-white">{project.budget}</span>
                      </div>
                    </div>

                    {/* Tasks */}
                    <div className="flex items-center justify-between pt-4 border-t border-white/5">
                      <span className="text-sm text-gray-400">
                        {project.completedTasks}/{project.tasks} tasks
                      </span>
                      <div className="flex gap-2">
                        <button className="p-2 rounded-lg bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 transition-colors">
                          <Eye className="w-4 h-4" />
                        </button>
                        <button className="p-2 rounded-lg bg-white/5 text-gray-400 hover:text-blue-400 hover:bg-blue-500/10 transition-colors">
                          <Edit3 className="w-4 h-4" />
                        </button>
                        <button className="p-2 rounded-lg bg-white/5 text-gray-400 hover:text-red-400 hover:bg-red-500/10 transition-colors">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Empty State */}
          {filteredProjects.length === 0 && (
            <div className="text-center py-12">
              <FolderKanban className="w-12 h-12 text-gray-500 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-white mb-2">No projects found</h3>
              <p className="text-gray-400">Try adjusting your search or filter</p>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default Projects;
